import React from 'react';
import { ChatPanel } from './ChatPanel';
import { NotesPanel } from './NotesPanel';
import { ParticipantsPanel } from './ParticipantsPanel';
import { WhiteboardPanel } from './WhiteboardPanel'; // ✅ IMPORT

export const SidePanel = ({
  activePanel,
  setActivePanel,
  messages,
  onSendMessage,
  roomId,
  companion,
  userId,
  onStopAI,
  startListening,
  stopListening,
  isListening,
  participants,
}) => {
  return (
    <div className="flex flex-col h-full">
      {/* Panel Content */}
      <div className="flex-1 overflow-hidden">
        {/* CHAT */}
        {activePanel === 'chat' && (
          <ChatPanel
            companion={companion}
            messages={messages}
            onSendMessage={onSendMessage}
            startListening={startListening}
            stopListening={stopListening}
            isListening={isListening}
            onStopAI={onStopAI}
          />
        )}

        {/* NOTES */}
        {activePanel === 'notes' && <NotesPanel roomId={roomId} />}

        {/* ✅ WHITEBOARD */}
        {activePanel === 'whiteboard' && <WhiteboardPanel />}

        {/* PARTICIPANTS */}
        {activePanel === 'participants' && (
          <div className="flex-1 overflow-y-auto p-4">
            {/* Header with Close Button */}
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold text-white">
                Participants ({participants.length})
              </h3>

              <button
                onClick={() => setActivePanel('chat')}
                className="p-2 hover:bg-gray-700 rounded-lg transition-colors"
              >
                <span className="text-white text-xl">✕</span>
              </button>
            </div>

            {/* Participants List */}
            <div className="space-y-2">
              {participants.map((participant, idx) => (
                <div
                  key={idx}
                  className="flex items-center gap-3 p-3 bg-gray-800 rounded-lg hover:bg-gray-750 transition-colors"
                >
                  <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center text-white font-bold">
                    {participant.userId.charAt(0).toUpperCase()}
                  </div>
                  
                  <div className="flex-1">
                    <p className="text-white font-medium text-sm">
                      {participant.userId}
                    </p>
                    <p className="text-gray-400 text-xs">
                      {participant.role}
                    </p>
                  </div>

                  {participant.isOnline && (
                    <div className="w-2 h-2 bg-green-500 rounded-full"></div>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};
